{"command":"$configPath = Join-Path $HOME '.superstack\config.json'
$promptedPath = Join-Path $HOME '.superstack\.telemetry-prompted'
$tier = 'anonymous'
if (Test-Path $configPath) {
  try { $cfg = Get-Content -Raw $configPath | ConvertFrom-Json; if ($cfg.telemetryTier) { $tier = [string]$cfg.telemetryTier } } catch {}
}
$prompted = if (Test-Path $promptedPath) { 'yes' } else { 'no' }
New-Item -ItemType Directory -Force (Join-Path $HOME '.superstack') | Out-Null
Write-Output "TELEMETRY: $tier"
Write-Output "TEL_PROMPTED: $prompted"
if ($tier -ne 'off') {
  $event = [ordered]@{skill='apply-grant';phase='launch';event='started';ts=(Get-Date).ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ssZ')} | ConvertTo-Json -Compress
  Add-Content -Path (Join-Path $HOME '.superstack\telemetry.jsonl') -Value $event -ErrorAction SilentlyContinue
}","workdir":"C:\Users\jauha\Documents\Antigravity_App\txguardian","timeout_ms":10000}

{"command":"$sessionsRoot = Join-Path $HOME '.codex\sessions'
$latest = Get-ChildItem -Path $sessionsRoot -Recurse -Filter *.jsonl -ErrorAction SilentlyContinue | Sort-Object LastWriteTime -Descending | Select-Object -First 1
if ($null -eq $latest) {
  Write-Output "NO_CODEX_SESSION_FOUND"
} else {
  $dest = Join-Path (Get-Location) 'codex-session.jsonl'
  Copy-Item -LiteralPath $latest.FullName -Destination $dest -Force
  Write-Output "EXPORTED_CODEX_SESSION=$dest"
  Write-Output "SOURCE=$($latest.FullName)"
  Write-Output "LAST_WRITE=$($latest.LastWriteTime.ToString('o'))"
  Write-Output "BYTES=$($latest.Length)"
}","workdir":"C:\Users\jauha\Documents\Antigravity_App\txguardian","timeout_ms":20000}
